-- Demo data. Loaded ONLY under the `demo` Spring profile (see application-demo.yml),
-- so a clean environment never inherits fake organizational structure.
--
-- Users are NOT seeded here: their passwords must be Argon2id-hashed, which SQL cannot
-- do. DemoUserSeeder (@Profile("demo")) creates them on startup, idempotently.

ON CONFLICT (code) DO NOTHING;

-- Departments --------------------------------------------------------------
ON CONFLICT (organization_id, code) DO NOTHING;

-- Teams --------------------------------------------------------------------
ON CONFLICT (organization_id, code) DO NOTHING;

-- Canonical skill vocabulary ------------------------------------------------
ON CONFLICT (organization_id, code) DO NOTHING;

-- Aliases: what an LLM actually writes, mapped onto the canonical code.
ON CONFLICT (skill_id, alias) DO NOTHING;

